import{z as i,x as A,o as r,c as d,q as s,j as n,D as E,d as l,s as B,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"选择投影连接的顺序","description":"","frontmatter":{"title":"选择投影连接的顺序","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/algebra-reorder.md","filePath":"cs/algebra-reorder.md","lastUpdated":1791063341000}'),p={name:"cs/algebra-reorder.md"};function m(C,a,h,D,c,u){const t=A("Mermaid");return r(),d("div",null,[a[2]||(a[2]=s('<h1 id="选择投影连接的顺序" tabindex="-1">选择投影连接的顺序 <a class="header-anchor" href="#选择投影连接的顺序" aria-label="Permalink to &quot;选择投影连接的顺序&quot;">​</a></h1><div class="epigraph"><p>同一表达式可以先选后连或先连后选；等价变换不改结果关系，只改中间结果有多大。</p><footer>—— 据 Codd 1972 代数；Ullman 对代数等价；Ramakrishnan and Gehrke</footer></div><p><a href="/cs/relational-algebra">上一课</a>给出选择、投影、连接等闭运算。本课不重推五种基本运算。缺口是：代数树的形状。先把两个大关系连接再选择，与先选择再连接，若谓词只涉及一侧，结果相同，页 I/O 差几个数量级。后课 SQL 优化器吃的就是这些律。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>代数是指称，不是执行计划。但课序马上要进声明语言与物理算子，必须先承认：<strong>连接结合律、选择下推、投影可穿连接</strong>（在无副作用、集合语义下）。缺口不是代价数字，而是「合法重排」这一层。NULL 与包语义会打破部分律，后课再钉。</p><p><span class="marginnote">术语翻译：选择下推就是把过滤条件沿表达式树往下搬，搬到离数据表最近的叶子上，让行数在参与连接之前先减下来。它是数据库优化器改写查询的第一板斧，「先过滤、再连接」说的就是这件事。</span></p><p><span class="marginnote">选择下推：σ 可以穿过一侧无该属性的连接，落到含该属性的叶子。投影要保留连接键，否则不能穿。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写同一查询的两棵树：σ–⋈ 与 ⋈–σ。用集合恒等说明它们相等。结合律让三点连接改括号。本课不算页数，只要求读者看到中间基数会变。物理算法下一单元才出现。</p><p><span class="marginnote">常见误区：初学者容易以为优化器改写查询会改变结果。实际上重排只在合法律（结合律、下推、投影保留连接键）的范围内进行，结果关系逐行相同；真正打破等价的是 NULL 和包（bag）语义下的重复行计数，那是后课单独处理的情况。</span></p>',10)),(r(),n(o,null,{default:E(()=>[B(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8C%E4%B8%80%E4%BB%A3%E6%95%B0%E8%A1%A8%E8%BE%BE%E5%BC%8F%22%5D%20--%3E%20T1%5B%22%E5%85%88%E8%BF%9E%E6%8E%A5%E5%90%8E%E9%80%89%E6%8B%A9%22%5D%0A%20%20Q%20--%3E%20T2%5B%22%E5%85%88%E9%80%89%E6%8B%A9%E5%90%8E%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20T1%20--%3E%20EQ%5B%22%E5%90%8C%E4%B8%80%E7%BB%93%E6%9E%9C%E5%85%B3%E7%B3%BB%22%5D%0A%20%20T2%20--%3E%20EQ%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"重排把「查询含义」与「操作顺序」分开，这是数据独立性在运算层的投影。后课代价估计给每棵物理树打分；没有本课的等价意识，优化器会被看成随便改用户 SQL。外键约束有时提供额外等价（存在性），本课不展开。",-1)),a[5]||(a[5]=e("p",null,"下推到底省在哪？同一个「取 R 地区为华北的行去连 S」的查询，两棵树中间结果相差几个数量级：",-1)),(r(),n(o,null,{default:E(()=>[B(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%CF%83%20%E5%9C%B0%E5%8C%BA%3D%E5%8D%8E%E5%8C%97%20(%20R%20%E2%8B%88%20S%20)%22%5D%20--%3E%20A%5B%22%E8%B7%AF%E7%BA%BF%E4%B8%80%EF%BC%9A%E5%85%88%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20A%20--%3E%20B%5B%22%E7%89%A9%E5%8C%96%20R%C3%97S%20%E9%87%8F%E7%BA%A7%E7%9A%84%E4%B8%AD%E9%97%B4%E7%BB%93%E6%9E%9C%22%5D%0A%20%20B%20--%3E%20C%5B%22%CF%83%20%E5%86%8D%E6%8A%8A%E7%BB%9D%E5%A4%A7%E5%A4%9A%E6%95%B0%E8%A1%8C%E6%89%94%E6%8E%89%22%5D%0A%20%20Q%20--%3E%20D%5B%22%E8%B7%AF%E7%BA%BF%E4%BA%8C%EF%BC%9A%E5%85%88%E4%B8%8B%E6%8E%A8%20%CF%83%20%E5%88%B0%20R%22%5D%0A%20%20D%20--%3E%20E%5B%22R%20%E5%8F%AA%E5%89%A9%E5%8D%8E%E5%8C%97%E7%9A%84%E8%A1%8C%22%5D%0A%20%20E%20--%3E%20F%5B%22%E7%94%A8%E5%B0%8F%E5%BE%97%E5%A4%9A%E7%9A%84%20R%20%E5%8E%BB%E8%BF%9E%20S%22%5D%0A%20%20C%20--%3E%20SAME%5B%22%E7%BB%93%E6%9E%9C%E5%85%B3%E7%B3%BB%E7%9B%B8%E5%90%8C%22%5D%0A%20%20F%20--%3E%20SAME%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">数字实例：设 R 有 100 万行、S 有 1 万行，选择谓词只留下 R 的 1%。先连后选要先物化可到 \\(10^{10}\\) 量级的连接结果再扔掉 99%；先选后连只剩约 \\(10^{4}\\) 行参与连接。结果一个字节不差，中间 I/O 差五六个数量级。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入外连接的全部非等价例子当主干，不把分布式下推到存储引擎的接口写完。如何用英文句子写查询，下一课 SQL 声明性。</p><p>后课默认：选择、投影、连接可以按律改序。语言层还没有。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>代数律允许改树而不改结果。</li><li>中间大小可变，代价是后课的事。</li><li>SQL 下一课。</li><li>出处：Codd 1972；Ullman；Ramakrishnan and Gehrke。</li></ul>',6))])}const b=i(p,[["render",m]]);export{f as __pageData,b as default};
